import{_ as s,o as a,c as o,a3 as t}from"./chunks/framework.CCylkYel.js";const m=JSON.parse('{"title":"Snapshots","description":"","frontmatter":{},"headers":[],"relativePath":"developers/commands/snapshots.md","filePath":"developers/commands/snapshots.md"}'),n={name:"developers/commands/snapshots.md"};function d(c,e,i,r,p,h){return a(),o("div",null,[...e[0]||(e[0]=[t(`<h1 id="snapshots" tabindex="-1">Snapshots <a class="header-anchor" href="#snapshots" aria-label="Permalink to &quot;Snapshots&quot;">​</a></h1><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loopback</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> snapshot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> knobs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loopback</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> snapshot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> arrange</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loopback</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> snapshot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> arrange</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repeat=loop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rate=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> knobs=0,5</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loopback</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> snapshot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sequence</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> knobs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loopback</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> snapshot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> morph</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> knobs</span></span></code></pre></div><p><code>PART</code> is <code>knobs</code>, <code>lfos</code>, or <code>rack0</code>…<code>rack7</code>.</p><h2 id="list-store-recall-delete-rename" tabindex="-1">List, store, recall, delete, rename <a class="header-anchor" href="#list-store-recall-delete-rename" aria-label="Permalink to &quot;List, store, recall, delete, rename&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Notes</th></tr></thead><tbody><tr><td><code>snapshot list [PART]</code></td><td>Names and occupancy. Default part is <code>knobs</code></td></tr><tr><td><code>snapshot store PART [SLOT|next] [NAME]</code></td><td>Capture live state. Empty-rack store is <code>BadRequest</code> until that rack has a device</td></tr><tr><td><code>snapshot recall PART SLOT</code></td><td>Queue a recall. Does not drop project-ready</td></tr><tr><td><code>snapshot delete PART SLOT</code></td><td>RAM + dirty</td></tr><tr><td><code>snapshot rename PART SLOT NAME</code></td><td>Names only; does not recapture</td></tr><tr><td><code>snapshot flags get|set device RACK DEV PARAM [on|off yes|no]</code></td><td>Per-parameter IN SNAPSHOT (<code>on</code>/<code>off</code>) and ALLOW MORPH (<code>yes</code>/<code>no</code>)</td></tr><tr><td><code>snapshot flags get|set lfo s32|cv16 INDEX PARAM [on|off yes|no]</code></td><td>Same flags for one S32 or CV16 LFO parameter</td></tr><tr><td><code>snapshot parent get|set lfo s32|cv16 INDEX [on|off]</code></td><td>IN SNAPSHOT for that whole LFO</td></tr><tr><td><code>snapshot parent get|set device RACK DEV [on|off]</code></td><td>IN SNAPSHOT for that whole MIDI device</td></tr><tr><td><code>snapshot copy|swap|move PART SRC DEST</code></td><td>Copy/swap/move persist payloads. Fade-blocked is <code>Busy</code>. Empty copy/move source is <code>NotFound</code></td></tr><tr><td><code>snapshot jump ROW</code></td><td>Jump the Arrange playhead to <code>ROW</code> (0–255). Same as <code>snapshot arrange jump ROW</code></td></tr><tr><td><code>snapshot queue ROW|off</code></td><td>Arm Drop on <code>ROW</code>, or <code>off</code>/<code>none</code>/<code>cancel</code> to clear. Same as <code>snapshot arrange queue</code></td></tr></tbody></table><p>Do not send store / recall / delete / copy / jump at a live user project over USB. Loopback and a throwaway CLI-HIL project (<code>SCENARIO=snapshots</code>) are the safe mutate paths.</p><h2 id="in-snapshot" tabindex="-1">IN SNAPSHOT <a class="header-anchor" href="#in-snapshot" aria-label="Permalink to &quot;IN SNAPSHOT&quot;">​</a></h2><p>Each macro, each whole LFO, and each whole MIDI device has one live IN SNAPSHOT switch. Each parameter has its own switch. Both default to on. Recall, fade, and morph move a parameter only when both switches are on. Off leaves that value where it is. Take still stores the whole scene. Recall does not write either switch, and the switches are not stored in the snapshot.</p><p><code>snapshot flags</code> reads and writes the per-parameter switch (and ALLOW MORPH). <code>snapshot parent</code> reads and writes the switch for a whole LFO or a whole MIDI device. <code>macro get</code> prints <code>in=on</code> or <code>in=off</code>, and <code>macro set … in=on|off</code> writes the switch for one macro. <code>lfo cfg set</code> does not change the LFO switch.</p><h2 id="morph" tabindex="-1">Morph <a class="header-anchor" href="#morph" aria-label="Permalink to &quot;Morph&quot;">​</a></h2><p><code>snapshot morph get|amount|clear PART …</code> — live fade toward one pad. <code>get</code> prints <code>pinA</code> unset and <code>pinB</code> as the target pad. Amount is 14-bit (<code>0</code>–<code>16383</code>). Above <code>0</code> it arms toward the occupied active slot, starting from what is playing now. <code>0</code> is your own sound: on a bank with no morph it is accepted and does nothing, and on a live morph it ends the morph once 0% is sounding (<code>get</code> then reads <code>morphing=0</code>). <code>clear</code> drops the fade. Firmware answers <code>Busy</code> while fade-on-recall owns the engine.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32&gt; snapshot morph amount knobs 8192</span></span>
<span class="line"><span>morph amount part=knobs 8192</span></span>
<span class="line"><span>s32&gt; snapshot morph get knobs</span></span>
<span class="line"><span>part=knobs pinA=- pinB=0 morphing=1 amount=8192</span></span>
<span class="line"><span>s32&gt; snapshot morph amount knobs 0</span></span>
<span class="line"><span>morph amount part=knobs 0</span></span>
<span class="line"><span>s32&gt; snapshot morph get knobs</span></span>
<span class="line"><span>part=knobs pinA=- pinB=- morphing=0 amount=0</span></span></code></pre></div><h2 id="sequence-one-column" tabindex="-1">Sequence (one column) <a class="header-anchor" href="#sequence-one-column" aria-label="Permalink to &quot;Sequence (one column)&quot;">​</a></h2><p><code>snapshot sequence get PART</code> and <code>snapshot sequence set PART rate=… [steps=…]</code> edit <strong>one</strong> Arrange column (up to 256 cells). <code>rate</code> is <code>1</code>–<code>128</code> bars (shared across the song). <code>steps</code> is up to 256 comma-separated slots or <code>rest</code>. Shorter lists pad with rest to the current song length.</p><h2 id="arrange-song-grid" tabindex="-1">Arrange (song grid) <a class="header-anchor" href="#arrange-song-grid" aria-label="Permalink to &quot;Arrange (song grid)&quot;">​</a></h2><p><code>snapshot arrange get</code> prints Repeat, Rate, <code>length</code> (4–256), live <code>song-row</code>, <code>drop-row</code> (<code>none</code> when no Drop is armed), then each part’s cells for that length.</p><p><code>snapshot arrange set</code> is GET-modify-SET. Pass only the fields you want to change:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32&gt; snapshot arrange set repeat=once rate=4 knobs=0,5 lfos=0,rest,3 rack0=0,2</span></span></code></pre></div><p><code>repeat</code> is <code>loop</code> or <code>once</code>. Column keys are the same part names as <code>snapshot list</code>. A short column list <strong>replaces that whole column</strong> and pads the rest of the song-length cells with <code>rest</code> (same as <code>snapshot sequence set</code>). Omitted columns keep their current cells. SET does <strong>not</strong> write Jump/Drop — use <code>snapshot jump</code> / <code>snapshot queue</code>. <code>view nav snapshot-lane</code> stays panel-only (<code>Forbidden</code>).</p><h2 id="mapping" tabindex="-1">Mapping <a class="header-anchor" href="#mapping" aria-label="Permalink to &quot;Mapping&quot;">​</a></h2><p><code>extmap add</code> / <code>macro set</code> accept <code>target=snapshot-slot</code> and <code>target=morph-amount</code> with <code>part=…</code>. An LFO cannot target either. A <code>target=morph-amount</code> macro has no MIN/MAX: <code>min=</code> and <code>max=</code> are ignored and <code>macro get</code> prints <code>min=0.000 max=16383.000</code>. <code>invert=</code> still flips it. The panel has no PICKUP row for it: a MORPH knob always picks up, whatever <code>pickup=</code> reads. A <code>target=snapshot-slot</code> macro’s <code>min=</code> and <code>max=</code> are snapshot slots <strong>1–32</strong>. The knob skips empty slots inside that window. Assigning that target with a number outside 1–32 uses the full 1–32 window. Changing <code>min=</code> or <code>max=</code> on a macro that is already a snapshot slot to a number outside 1–32 is refused. <code>in=</code> is forced off for both targets (<code>macro get</code> prints <code>in=off</code>).</p><p>To make either one a normal macro again, give it a new <code>mode=</code> (or <code>rack=</code>, <code>device=</code>, <code>param=</code>, <code>cvParam=</code>) without <code>target=</code>. The macro leaves the snapshot role, <code>in=</code> turns back on, and MIN/MAX become the new mode&#39;s full range. A device setting gets its own range from the S32 (Delay Time reads 0–1000). Add <code>in=</code>, <code>min=</code>, or <code>max=</code> to the same sentence to set them yourself:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32&gt; macro set 0 0 mode=cc msb=7</span></span>
<span class="line"><span>s32&gt; macro get 0 0</span></span>
<span class="line"><span>pot 0 macro 0: mode=cc msb=7 … min=0.000 max=127.000 … in=on … cvOut=255 lfo=255 name=</span></span></code></pre></div>`,23)])])}const g=s(n,[["render",d]]);export{m as __pageData,g as default};
